components.css:
.ds-btn-primary {
  background: #9f5f6d;
  color: #ffffff;
  font-family: 'Schibsted Grotesk', ui-sans-serif, system-ui, sans-serif;
  font-size: 14px;
  font-weight: 400;
  line-height: 1.55;
  padding: 10px 16px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 120ms cubic-bezier(0.25, 1, 0.5, 1);
}
.ds-btn-primary:hover { background: #8a4d5a; }
.ds-btn-primary:focus-visible { outline: 2px solid #9f5f6d; outline-offset: 2px; }
.ds-btn-primary:active { background: #7a4049; }
.ds-btn-primary:disabled { background: #f4eef1; color: #9e7e88; cursor: not-allowed; }

.ds-btn-secondary {
  background: #ffffff;
  color: #5d4037;
  font-family: 'Schibsted Grotesk', ui-sans-serif, system-ui, sans-serif;
  font-size: 14px;
  padding: 10px 16px;
  border: 1px solid #a58a91;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 120ms cubic-bezier(0.25, 1, 0.5, 1), border-color 120ms cubic-bezier(0.25, 1, 0.5, 1);
}
.ds-btn-secondary:hover { background: #fdf2f5; border-color: #5d4037; }
.ds-btn-secondary:focus-visible { outline: 2px solid #9f5f6d; outline-offset: 2px; }

.ds-field-notch { position: relative; display: inline-block; width: 220px; margin: 4px 12px 16px 0; }
.ds-notch-label {
  position: absolute;
  top: -9px;
  left: 10px;
  padding: 0 4px;
  background: var(--surface-bg, #fff9fb); /* hereda de la superficie que lo contiene: body, Card, Modal... */
  font-family: 'PT Mono', ui-monospace, monospace;
  font-size: 12px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #785a63;
  transition: color 120ms cubic-bezier(0.25, 1, 0.5, 1);
}
.ds-notch-input {
  width: 100%;
  padding: 11px 12px;
  font-family: 'Schibsted Grotesk', sans-serif;
  font-size: 14px;
  color: #5d4037;
  background: #fffcfd;
  border: 1.5px solid #a58a91;
  border-radius: 8px;
  transition: border-color 120ms cubic-bezier(0.25, 1, 0.5, 1);
}
.ds-notch-input:focus { outline: none; border-color: #9f5f6d; }
.ds-notch-input:focus + .ds-notch-label,
.ds-notch-label--focus { color: #9f5f6d; }
.ds-notch-input--focus { border-color: #9f5f6d; }
.ds-notch-label--error { color: #b84c58; }
.ds-notch-input--error { border-color: #b84c58; }
.ds-notch-help { display: block; margin-top: 6px; font-size: 13px; color: #b84c58; }

.ds-select { display: flex; align-items: center; justify-content: space-between; gap: 8px; width: 220px; background: #fffcfd; color: #5d4037; font-family: 'Schibsted Grotesk', sans-serif; font-size: 14px; padding: 9px 12px; border: 1px solid #a58a91; border-radius: 8px; cursor: pointer; }
.ds-select:focus-visible { outline: none; border-color: #9f5f6d; box-shadow: 0 0 0 2px rgba(159,95,109,0.2); }
.ds-select-menu { list-style: none; margin: 4px 0 0; padding: 4px; width: 220px; background: #ffffff; border: 1px solid #a58a91; border-radius: 8px; box-shadow: 0 8px 24px -6px rgba(93,64,55,0.18); font-family: 'Schibsted Grotesk', sans-serif; font-size: 14px; }
.ds-select-option { padding: 8px 10px; border-radius: 6px; display: flex; align-items: center; justify-content: space-between; }
.ds-select-option--highlighted { background: #f4eef1; }
.ds-select-option--selected { background: #ffb7c5; color: #5d4037; }
.ds-select-option--selected svg { flex-shrink: 0; }

.ds-checkbox { display: inline-flex; align-items: center; gap: 8px; font-family: 'Schibsted Grotesk', sans-serif; font-size: 14px; color: #5d4037; cursor: pointer; }
.ds-checkbox input { position: absolute; opacity: 0; width: 18px; height: 18px; }
.ds-checkbox-box { width: 18px; height: 18px; border: 1px solid #a58a91; border-radius: 6px; display: inline-flex; align-items: center; justify-content: center; background: #ffffff; }
.ds-checkbox input:checked + .ds-checkbox-box { background: #9f5f6d; border-color: #9f5f6d; color: #ffffff; }
.ds-checkbox input:focus-visible + .ds-checkbox-box { outline: 2px solid #9f5f6d; outline-offset: 2px; }

.ds-badge { font-family: 'PT Mono', ui-monospace, monospace; font-size: 12px; letter-spacing: 0.06em; text-transform: uppercase; padding: 3px 10px; border-radius: 999px; display: inline-block; }
.ds-badge--neutral { background: #f4eef1; color: #785a63; }
.ds-badge--positive { background: #b2e2d2; color: #2d4a3e; }
.ds-badge--attention { background: #fff0c2; color: #816829; }
.ds-badge--negative { background: #ffcdd6; color: #b84c58; }

.ds-nav { display: flex; flex-direction: column; gap: 2px; font-family: 'Schibsted Grotesk', sans-serif; font-size: 14px; width: 200px; }
.ds-nav-item { color: #785a63; text-decoration: none; padding: 8px 12px; border-radius: 6px; }
.ds-nav-item:hover { background: #fdf2f5; }
.ds-nav-item:focus-visible { outline: 2px solid #9f5f6d; outline-offset: 2px; }
.ds-nav-item--active { background: #ffb7c5; color: #5d4037; }

.ds-table { width: 100%; border-collapse: collapse; font-family: 'Schibsted Grotesk', sans-serif; font-size: 14px; color: #5d4037; }
.ds-table thead th { font-family: 'PT Mono', ui-monospace, monospace; font-size: 12px; letter-spacing: 0.06em; text-transform: uppercase; color: #785a63; text-align: left; padding: 10px 12px; border-bottom: 1px solid #a58a91; }
.ds-table tbody td { padding: 10px 12px; border-bottom: 1px solid #ffe1e9; font-family: 'PT Mono', ui-monospace, monospace; }
.ds-table-num { text-align: right; font-variant-numeric: tabular-nums; }
.ds-table-row--hover td { background: #fdf7f8; }

.ds-wordmark { display: inline-flex; align-items: center; gap: 6px; font-family: 'Schibsted Grotesk', sans-serif; font-size: 20px; font-weight: 600; color: #5d4037; }
.ds-sparkle { fill: #816829; }
.ds-sparkle--outline { width: 16px; height: 16px; }
.ds-sparkle--fill { width: 28px; height: 28px; }
.ds-sparkle-moment { display: flex; flex-direction: column; align-items: center; gap: 8px; padding: 8px 16px; }
.ds-sparkle-moment p { margin: 0; font-family: 'Schibsted Grotesk', sans-serif; font-size: 14px; color: #5d4037; }
